import time
def gweights(gtr, gw=(1, 1, 1, 1)):
    sw = np.zeros(len(gtr))
    for q in range(4): sw[gtr==q] = gw[q]/np.sum(gtr==q)
    return sw*len(gtr)/sw.sum()
def fit_logreg(Xtr, ytr, gtr, C=0.01, gw=(1, 1, 1, 1), penalty='l2'):
    mu_, sd_ = Xtr.mean(0), Xtr.std(0) + 1e-6
    Z = (Xtr - mu_)/sd_
    if penalty == 'l2': clf = LogisticRegression(C=C, max_iter=3000, tol=1e-6)
    else: clf = LogisticRegression(C=C, penalty='l1', solver='liblinear', max_iter=3000, tol=1e-5)
    clf.fit(Z, ytr, sample_weight=gweights(gtr, gw))
    w2 = clf.coef_[0]/sd_; b2 = clf.intercept_[0] - w2@mu_
    return w2, b2
def fit_ridge(Xtr, ytr, gtr, lam=1.0, gw=(1, 1, 1, 1)):
    mu_, sd_ = Xtr.mean(0), Xtr.std(0) + 1e-6
    Z = (Xtr - mu_)/sd_; sw = gweights(gtr, gw); t = 2.0*ytr - 1
    zm = (sw[:, None]*Z).sum(0)/sw.sum(); tm = (sw*t).sum()/sw.sum(); Zc = Z - zm
    # dual form (n < d): w = Zc^T (K + lam I)^-1 ... with weights
    s = np.sqrt(sw); A = Zc*s[:, None]; K = A@A.T
    a = np.linalg.solve(K + lam*np.eye(len(t)), s*(t - tm)); wz = A.T@a
    w2 = wz/sd_; b2 = tm - wz@zm - w2@mu_
    return w2, b2
